static
void kernel_symm(int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  DATA_TYPE temp2;

//BLAS PARAMS
//SIDE = 'L'
//UPLO = 'L'
// =>  Form  C := alpha*A*B + beta*C
// A is MxM
// B is MxN
// C is MxN
//note that due to Fortran array layout, the code below more closely resembles upper triangular case in BLAS
#pragma scop
  const int TI = 64;
  const int TJ = 64;
  int ii, jj, ii_end, jj_end;

  // Loop1: Update C[k][j] for all k, j, and for i from k+1 to M-1
  #pragma omp parallel for default(none) shared(C, B, A, alpha) private(k, i, jj, j, jj_end) schedule(dynamic, 16)
  for (k = 0; k < _PB_M; k++) {
    for (i = k+1; i < _PB_M; i++) {
      for (jj = 0; jj < _PB_N; jj += TJ) {
        jj_end = min(jj+TJ, _PB_N);
